<script setup lang="ts">
import { computed, ref } from 'vue'
import { ArrowLeft, ArrowRight, Box, ChevronRight, Clock3, Folder, Images, Info, Layers3, LayoutDashboard, Monitor, MoreHorizontal, PackageCheck, Plus, Search, Settings2, TrainFront } from '@lucide/vue'
import { t } from '../i18n'

type Section = 'overview' | 'all' | 'trains' | 'decorations' | 'pids' | 'assets' | 'settings'
const section = ref<Section>('overview')
const query = ref('')
const message = ref('')
const examples = computed(() => [
  { id: 'a', name: t('sampleTrainA'), detail: t('sampleTrainAInfo'), modified: t('sampleToday'), tone: 'blue' },
  { id: 'b', name: t('sampleTrainB'), detail: t('sampleTrainBInfo'), modified: t('sampleYesterday'), tone: 'amber' },
  { id: 'c', name: t('sampleTrainC'), detail: t('sampleTrainCInfo'), modified: t('sampleEarlier'), tone: 'steel' },
])
const visibleExamples = computed(() => examples.value.filter(item => item.name.toLowerCase().includes(query.value.toLowerCase())))
const currentTitle = computed(() => ({
  overview: t('projectOverview'), all: t('allContent'), trains: t('trains'), decorations: t('decorativeObjects'),
  pids: t('pids'), assets: t('assets'), settings: t('projectSettings'),
})[section.value])
function goHome() { window.location.assign(window.location.pathname) }
function showUpcoming() { message.value = t('trainEditorUpcoming') }
</script>

<template>
  <div class="workbench-preview">
    <div class="projectbar">
      <button class="projectbar-back" :aria-label="t('back')" @click="goHome"><ArrowLeft :size="19" /></button>
      <span class="projectbar-trail" @click="goHome">{{ t('home') }}</span><ChevronRight :size="14" class="crumb-chevron" />
      <strong>{{ t('previewProject') }}</strong><span class="projectbar-badge">{{ t('projectTarget') }}</span>
      <div class="projectbar-spacer"></div>
      <span class="preview-pill"><span></span>{{ t('previewLabel') }}</span>
      <button class="export-button" @click="message = t('exportPreview')"><PackageCheck :size="17" />{{ t('exportPack') }}</button>
    </div>

    <div class="workbench-body">
      <aside class="workbench-sidebar">
        <div class="project-identity-panel"><div class="project-icon"><TrainFront :size="29" :stroke-width="1.6" /></div><div><strong>{{ t('previewProject') }}</strong><span>{{ t('projectTarget') }}</span></div></div>
        <nav aria-label="Project navigation">
          <button :class="['workspace-nav-item', { active: section === 'overview' }]" @click="section = 'overview'"><LayoutDashboard :size="19" />{{ t('overview') }}</button>
          <div class="workspace-nav-heading">{{ t('content') }}</div>
          <button :class="['workspace-nav-item', { active: section === 'all' }]" @click="section = 'all'"><Layers3 :size="19" />{{ t('allContent') }}<span class="nav-count">3</span></button>
          <button :class="['workspace-nav-item', { active: section === 'trains' }]" @click="section = 'trains'"><TrainFront :size="19" />{{ t('trains') }}<span class="nav-count">3</span></button>
          <button :class="['workspace-nav-item', { active: section === 'decorations' }]" @click="section = 'decorations'"><Box :size="19" />{{ t('decorativeObjects') }}<span class="nav-coming">{{ t('planned') }}</span></button>
          <button :class="['workspace-nav-item', { active: section === 'pids' }]" @click="section = 'pids'"><Monitor :size="19" />{{ t('pids') }}<span class="nav-coming">{{ t('planned') }}</span></button>
          <div class="workspace-nav-heading secondary-heading">{{ t('projectGroup') }}</div>
          <button :class="['workspace-nav-item', { active: section === 'assets' }]" @click="section = 'assets'"><Images :size="19" />{{ t('assets') }}</button>
          <button :class="['workspace-nav-item', { active: section === 'settings' }]" @click="section = 'settings'"><Settings2 :size="19" />{{ t('projectSettings') }}</button>
        </nav>
        <div class="sidebar-preview-note"><Info :size="16" /><span>{{ t('previewNote') }}</span></div>
      </aside>

      <main class="workspace-content">
        <template v-if="section === 'overview'">
          <div class="workspace-page-heading"><div><div class="workspace-eyebrow">{{ t('previewLabel') }}</div><h1>{{ t('projectOverview') }}</h1><p>{{ t('overviewSubtitle') }}</p></div><button class="primary-workspace-button" @click="showUpcoming"><Plus :size="18" />{{ t('newTrain') }}</button></div>
