          <section class="workspace-stats"><div class="stat-card"><span>{{ t('totalItems') }}</span><strong>03</strong><small>{{ t('content') }}</small></div><div class="stat-card"><span>{{ t('trainCount') }}</span><strong>03</strong><small>{{ t('availableNow') }}</small></div><div class="stat-card"><span>{{ t('assetCount') }}</span><strong>12</strong><small>{{ t('assets') }}</small></div></section>
          <div class="workspace-section-head"><div><span class="workspace-eyebrow">{{ t('content') }}</span><h2>{{ t('contentTypes') }}</h2><p>{{ t('contentTypesHint') }}</p></div></div>
          <div class="category-grid"><button class="category-card" @click="section = 'trains'"><span class="category-icon train"><TrainFront :size="25" /></span><strong>{{ t('trains') }}</strong><small>{{ t('trainsDescription') }}</small><span class="category-footer">03 {{ t('totalItems') }}<ArrowRight :size="16" /></span></button><button class="category-card" @click="section = 'decorations'"><span class="category-icon"><Box :size="25" /></span><strong>{{ t('decorativeObjects') }}</strong><small>{{ t('decorativeDescription') }}</small><span class="category-footer">{{ t('planned') }}<ArrowRight :size="16" /></span></button><button class="category-card" @click="section = 'pids'"><span class="category-icon"><Monitor :size="25" /></span><strong>{{ t('pids') }}</strong><small>{{ t('pidsDescription') }}</small><span class="category-footer">{{ t('planned') }}<ArrowRight :size="16" /></span></button></div>
          <div class="workspace-section-head recent-head"><div><span class="workspace-eyebrow">{{ t('continueWorking') }}</span><h2>{{ t('recentContent') }}</h2></div><button class="view-all" @click="section = 'all'">{{ t('viewAll') }}<ArrowRight :size="16" /></button></div>
          <div class="recent-list"><button v-for="item in examples.slice(0, 2)" :key="item.id" class="recent-item" @click="showUpcoming"><span :class="['item-thumb', item.tone]"><TrainFront :size="25" /></span><span class="recent-item-copy"><strong>{{ item.name }}</strong><small>{{ item.detail }}</small></span><span class="recent-item-time"><Clock3 :size="13" />{{ item.modified }}</span><ChevronRight :size="17" /></button></div>
        </template>

        <template v-else>
          <div class="workspace-page-heading"><div><div class="workspace-eyebrow">{{ t('previewLabel') }}</div><h1>{{ currentTitle }}</h1><p>{{ section === 'all' || section === 'trains' ? t('trainsDescription') : t('upcomingMessage') }}</p></div><button v-if="section === 'all' || section === 'trains'" class="primary-workspace-button" @click="showUpcoming"><Plus :size="18" />{{ t('newTrain') }}</button></div>
          <template v-if="section === 'all' || section === 'trains'"><div class="content-toolbar"><label><Search :size="18" /><input v-model="query" :placeholder="t('searchContent')" /></label><span>03 {{ t('totalItems') }}</span></div><div class="content-table"><div class="content-table-head"><span>{{ t('name') }}</span><span>{{ t('type') }}</span><span>{{ t('modified') }}</span><span>{{ t('actions') }}</span></div><button v-for="item in visibleExamples" :key="item.id" class="content-table-row" @click="showUpcoming"><span class="content-name"><span :class="['item-thumb', item.tone]"><TrainFront :size="23" /></span><span><strong>{{ item.name }}</strong><small>{{ item.detail }}</small></span></span><span>{{ t('trains') }}</span><span>{{ item.modified }}</span><MoreHorizontal :size="19" /></button></div></template>
          <div v-else class="planned-panel"><div class="planned-icon"><component :is="section === 'decorations' ? Box : section === 'pids' ? Monitor : section === 'assets' ? Images : Folder" :size="34" /></div><h2>{{ currentTitle }}</h2><p>{{ t('upcomingMessage') }}</p><span>{{ t('planned') }}</span></div>
        </template>
      </main>
    </div>
    <div v-if="message" class="workspace-toast" role="status">{{ message }}<button @click="message = ''">×</button></div>
  </div>
</template>

